using System;
using System.Drawing;
using System.Windows.Forms;

private Label lblClock;
private Button btnToggle;
private Timer timer1;

public ExampleForm()
{
    Text = "Timer example";
    ClientSize = new Size(300, 140);
    InitializeComponents();
}

lblClock = new Label();
lblClock.Font = new Font("Segoe UI", 20F);
lblClock.AutoSize = true;
lblClock.Location = new Point(20, 20);
lblClock.Text = DateTime.Now.ToLongTimeString();

timer1 = new Timer();
timer1.Interval = 1000;
timer1.Tick += Timer1_Tick;
timer1.Start();

btnToggle = new Button();
btnToggle.Text = "Pause";
btnToggle.Location = new Point(20, 80);
btnToggle.Click += BtnToggle_Click;

private void Timer1_Tick(object sender, EventArgs e)
{
    lblClock.Text = DateTime.Now.ToLongTimeString();
}

private void BtnToggle_Click(object sender, EventArgs e)
{
    timer1.Enabled = !timer1.Enabled;
    btnToggle.Text = timer1.Enabled ? "Pause" : "Resume";
}

    [STAThread]
    static void Main()
    {
        Application.EnableVisualStyles();
        Application.Run(new ExampleForm());
    }
}

using System;
using System.ComponentModel;
using System.Drawing;
using System.Windows.Forms;

private BackgroundWorker worker;
private ProgressBar progress;
private Button btnStart;
private Button btnCancel;

public ExampleForm()
{
    Text = "BackgroundWorker example";
    ClientSize = new Size(360, 120);
    InitializeComponents();
}

worker = new BackgroundWorker();
worker.WorkerReportsProgress = true;
worker.WorkerSupportsCancellation = true;

worker.DoWork += Worker_DoWork;
worker.ProgressChanged += Worker_ProgressChanged;
worker.RunWorkerCompleted += Worker_RunWorkerCompleted;

progress = new ProgressBar();
progress.Location = new Point(20, 20);
progress.Size = new Size(300, 24);

btnStart = new Button();
btnStart.Text = "Start";
btnStart.Location = new Point(20, 60);
btnStart.Click += BtnStart_Click;

btnCancel = new Button();
btnCancel.Text = "Cancel";
btnCancel.Location = new Point(110, 60);
btnCancel.Click += BtnCancel_Click;

Controls.Add(progress);
Controls.Add(btnStart);
Controls.Add(btnCancel);

private void BtnStart_Click(object sender, EventArgs e)
{
    if (!worker.IsBusy)
    {
        progress.Value = 0;
        worker.RunWorkerAsync();
    }
}

private void BtnCancel_Click(object sender, EventArgs e)
{
    worker.CancelAsync();
}

private void Worker_DoWork(object sender, DoWorkEventArgs e)
{
    for (int i = 1; i <= 100; i++)
    {
        if (worker.CancellationPending)
        {
            e.Cancel = true;
            return;
        }

        System.Threading.Thread.Sleep(30);
        worker.ReportProgress(i);
    }
}

private void Worker_ProgressChanged(object sender, ProgressChangedEventArgs e)
{
    progress.Value = e.ProgressPercentage;
}

private void Worker_RunWorkerCompleted(object sender, RunWorkerCompletedEventArgs e)
{
    MessageBox.Show(e.Cancelled ? "Cancelled." : "Finished!");
}

    [STAThread]
    static void Main()
    {
        Application.EnableVisualStyles();
        Application.Run(new ExampleForm());
    }
}

using System;
using System.Drawing;
using System.Windows.Forms;

private NotifyIcon notifyIcon1;
private ContextMenuStrip trayMenu;
private ToolStripMenuItem exitItem;

public ExampleForm()
{
    Text = "NotifyIcon example";
    ClientSize = new Size(300, 100);
    InitializeComponents();
}

trayMenu = new ContextMenuStrip();
exitItem = new ToolStripMenuItem("Exit");
exitItem.Click += ExitItem_Click;
trayMenu.Items.Add(exitItem);

notifyIcon1 = new NotifyIcon();
notifyIcon1.Icon = SystemIcons.Application;
notifyIcon1.Text = "My Application";
notifyIcon1.ContextMenuStrip = trayMenu;

private void ExitItem_Click(object sender, EventArgs e)
{
    notifyIcon1.Visible = false;
    Application.Exit();
}

private void NotifyIcon1_MouseDoubleClick(object sender, MouseEventArgs e)
{
    Show();
    WindowState = FormWindowState.Normal;
}

    [STAThread]
    static void Main()
    {
        Application.EnableVisualStyles();
        Application.Run(new ExampleForm());
    }
}
